import collections

class Solution:
    def groupAnagrams(self, strs: list[str]) -> list[list[str]]:
        str_map = collections.defaultdict(list)

        for string in strs :
            counts = [0]*26
            for c in string:
                counts[ord(c)-ord("a")] += 1
            str_map[tuple(counts)].append(string)
        return str_map.values()

