class Solution:
    def findOriginalArray(self, changed: List[int]) -> List[int]:
        if len(changed) <= 1:
            return []
        sorted_changed = sorted(changed)
        freq_map = collections.Counter(sorted_changed)
        results = []
        for num in sorted_changed:
            if freq_map[num] > 0:
                freq_map[num] -= 1
                if freq_map[num*2] > 0:
                    freq_map[num*2] -= 1
                    results.append(num)
                else:
                    return []
        return results

