class Solution:
    def makeSmallestPalindrome(self, s: str) -> str:

        l, r = 0, len(s) - 1
        s_list = list(s)

        while l < r:
            if s_list[l] != s_list[r]:
                if ord(s_list[l]) < ord(s_list[r]):
                    s_list[r] = s_list[l]
                else:
                    s_list[l] = s_list[r]
            l += 1
            r -= 1
        return "".join(s_list)

class Solution:
    def smallestString(self, s: str) -> str:
        s = list(s)
        n = len(s)
        i = 0

        # Skip leading 'a's
        while i < n and s[i] == 'a':
            i += 1

        # If the entire string is 'a's, change the last character to 'z'
        if i == n:
            s[-1] = 'z'
        else:
            # Replace characters with their preceding letter until we hit an 'a' or end of string
            while i < n and s[i] != 'a':
                s[i] = chr(ord(s[i]) - 1)
                i += 1

        return ''.join(s)

