class Solution:
    def twoSum(self, numbers: List[int], target: int) -> List[int]:
        i = 0  # Pointer for the start of the array
        j = len(numbers) - 1  # Pointer for the end of the array

        while i < j:
            current_sum = numbers[i] + numbers[j]

            if current_sum == target:
                # Found the pair, return indices (1-indexed)
                return [i + 1, j + 1]
            elif current_sum < target:
                # Sum is too small, move left pointer to the right
                i += 1
            else:
                # Sum is too large, move right pointer to the left
                j -= 1

        # If no solution is found (should not happen given the problem constraints)
        return []

class Solution:
    def twoSum(self, nums: list[int], k: int, result: list[list[int]], target: int) -> None:
            """
            Helper function to find pairs that sum up to the target.
            Uses two-pointer technique on a sorted array.
            """
            i, j = k, len(nums) - 1
            while i < j:
                current_sum = nums[i] + nums[j]
                if current_sum > target:
                    j -= 1  # Sum too large, decrease right pointer
                elif current_sum < target:
                    i += 1  # Sum too small, increase left pointer
                else:
                    # Found a triplet, add to result
                    result.append([-target, nums[i], nums[j]])
                    # Skip duplicates for both pointers
                    while i < j and nums[i] == nums[i+1]:
                        i += 1
                    while i < j and nums[j] == nums[j-1]:
                        j -= 1
                    # Move both pointers
                    i += 1
                    j -= 1

class Solution:
    def threeSumClosest(self, nums: list[int], target: int) -> int:
        n = len(nums)
        nums.sort()  # Sort the array to use two-pointer technique

        closest_sum = float('inf')  # Initialize with positive infinity

        for i in range(n - 2):  # Iterate up to third last element
            left = i + 1
            right = n - 1

            while left < right:
                current_sum = nums[i] + nums[left] + nums[right]

                # Update closest_sum if current_sum is closer to target
                if abs(target - current_sum) < abs(target - closest_sum):
                    closest_sum = current_sum

                if current_sum > target:
                    right -= 1  # Sum too large, decrease right pointer
                else:
                    left += 1  # Sum too small or equal, increase left pointer

                # Optional optimization: if we found the target, we can return immediately
                if closest_sum == target:
                    return closest_sum

        return closest_sum

