from collections import Counter

def count_anagram_occurrences(text, pattern):
    pattern_freq = Counter(pattern)
    distinct_char_count = len(pattern_freq)  # Count of distinct characters in pattern
    anagram_count = 0  # Answer: count of anagram occurrences
    n, k = len(text), len(pattern)

    i, j = 0, 0  # Window pointers

    while j < n:
        # Process the current character
        if text[j] in pattern_freq:
            pattern_freq[text[j]] -= 1
            if pattern_freq[text[j]] == 0:
                distinct_char_count -= 1

        # If window size is less than pattern length, expand window
        if j - i + 1 < k:
            j += 1
        # If window size equals pattern length
        elif j - i + 1 == k:
            # Check if we found an anagram
            if distinct_char_count == 0:
                anagram_count += 1

            # Slide the window
            if text[i] in pattern_freq:
                pattern_freq[text[i]] += 1
                if pattern_freq[text[i]] == 1:
                    distinct_char_count += 1

            i += 1
            j += 1

    return anagram_count

class Solution:
    def minWindow(self, s: str, t: str) -> str:

            from collections import Counter

            def valid_window(freq_counter: Counter, req_freq: Counter) -> bool:
                for char in req_freq:
                    if req_freq[char] > freq_counter.get(char, 0):
                        return False
                return True

            def adjust_valid_window(s, window_start, window_end, freq_counter, req_freq):
                while window_start < window_end:
                    char_to_remove = s[window_start]
                    freq_counter[char_to_remove] -= 1
                    if valid_window(freq_counter, req_freq):
                        window_start += 1
                    else:
                        freq_counter[char_to_remove] += 1
                        break
                return window_start

            minimum_window = [0, 0]
            minimum_window_len = float('inf')
            window_start = 0
            window_end = 0
            freq_counter = Counter()
            req_freq = Counter(t)

            while window_end < len(s):
                current_char = s[window_end]
                freq_counter[current_char] += 1
                # Check if the current frequency in the window matches the freq of the required_freq
                if valid_window(freq_counter, req_freq):
                    new_start = adjust_valid_window(s, window_start, window_end, freq_counter, req_freq)
                    window_start = new_start
                    new_window_size = window_end - new_start + 1
                    if new_window_size < minimum_window_len:
                        minimum_window = [window_start, window_end+1]
                        minimum_window_len = new_window_size
                window_end += 1
            return s[minimum_window[0]: minimum_window[1]]

def longest_substring_k_repeating(s, k):
    if k == 1:
        return len(s)

    max_length = 0
    for unique in range(1, 27):  # maximum 26 unique characters
        char_freq = {}
        i = j = 0
        unique_count = 0
        k_count = 0
        n = len(s)

        while j < n:
            # Update character frequency
            if s[j] not in char_freq:
                char_freq[s[j]] = 1
                unique_count += 1
            else:
                char_freq[s[j]] += 1

            if char_freq[s[j]] == k:
                k_count += 1

            # If we have more unique characters than allowed, shrink the window
            while unique_count > unique:
                char_freq[s[i]] -= 1
                if char_freq[s[i]] == 0:
                    unique_count -= 1
                if char_freq[s[i]] == k - 1:
                    k_count -= 1
                i += 1

            # If all characters in the current window are k-repeating
            if unique_count == k_count == unique:
                max_length = max(max_length, j - i + 1)

            j += 1

    return max_length

