def maxSlidingWindow(self, nums: list[int], k: int) -> list[int]:

    from collections import deque
    # Store the indexes of the elements in the array within the window
    dq = deque()
    res = []

    for i in range(k):
        while dq and nums[i] >= nums[dq[-1]]:
            dq.pop()
        dq.append(i)

    res.append(nums[dq[0]])

    for i in range(k, len(nums)):
        if dq and dq[0] == i - k:
            dq.popleft()
        while dq and nums[i] >= nums[dq[-1]]:
            dq.pop()

        dq.append(i)
        res.append(nums[dq[0]])

    return res

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        nums.sort()
        curr_total = 0
        left = 0
        curr_max_freq =0

        for right in range(0, len(nums)):
            curr_total += nums[right]

            while nums[right]* (right-left+1) > curr_total+k:
                curr_total -= nums[left]
                left += 1
            curr_max_freq = max( curr_max_freq, right-left+1)
        return curr_max_freq

def order_agnostic_binary_search(arr: list[int], target: int) -> int:

    if not arr:
        return -1

    left, right = 0, len(arr) - 1

    # Determine the sorting order
    is_ascending = arr[left] < arr[right]

    while left <= right:
        mid = left + (right - left) // 2  # Avoid potential integer overflow

        if arr[mid] == target:
            return mid

        if is_ascending:
            if target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if target > arr[mid]:
                right = mid - 1
            else:
                left = mid + 1

    return -1

def search_nearly_sorted(arr, target, k):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        # Check if the middle element is the target
        if arr[mid] == target:
            return mid

        # Check k elements on left and right of mid
        start = max(mid - k, 0)
        end = min(mid + k, len(arr) - 1)

        for i in range(start, end + 1):
            if arr[i] == target:
                return i

        # If target is smaller, search in the left half
        if arr[mid] > target:
            right = mid - k - 1
        # If target is larger, search in the right half
        else:
            left = mid + k + 1

    return -1

def mySqrt(x: int) -> int:
    if x == 0 or x == 1:
        return x

    left, right = 1, x
    result = 0

    while left <= right:
        mid = (left + right) // 2

        if mid * mid == x:
            return mid

        if mid * mid > x:
            right = mid - 1
        else:
            left = mid + 1
            result = mid  # Keep track of the last valid answer

    return result

def find_rotation_count(arr):
    left, right = 0, len(arr) - 1

    # If the array is not rotated at all
    if arr[left] <= arr[right]:
        return 0

    while left <= right:
        # If the first element is less than the last element,
        # then we have found the smallest element
        if arr[left] <= arr[right]:
            return left

        mid = (left + right) // 2
        next_mid = (mid + 1) % len(arr)
        prev_mid = (mid - 1 + len(arr)) % len(arr)

        # Check if mid element is the smallest
        if arr[mid] <= arr[next_mid] and arr[mid] <= arr[prev_mid]:
            return mid

        # If the right half is sorted, the pivot must be in the left half
        elif arr[mid] <= arr[right]:
            right = mid - 1

        # If the left half is sorted, the pivot must be in the right half
        elif arr[left] <= arr[mid]:
            left = mid + 1

    return 0

