def search_rotated_array(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        # Check if the left half is sorted
        if arr[left] <= arr[mid]:
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # If the left half is not sorted, the right half must be sorted
        else:
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def search_rotated_array_duplicates(arr, target):
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return True

        # If we can't determine which half to search, reduce the search space
        if arr[left] == arr[mid] == arr[right]:
            left += 1
            right -= 1

        # If the left half is sorted
        elif arr[left] <= arr[mid]:
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1

        # If the right half is sorted
        else:
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return False

def binary_search(arr, left, right, target):
    # Perform binary search in the given range of the array.
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def find_in_infinite_array(arr, target):

    #Find the position of the target element in an infinite sorted array.

    # Start with a box of size 1
    left, right = 0, 1

    # Exponentially increase the box size until we find a range that contains the target
    while right < len(arr) and arr[right] < target:
        left = right
        right = right * 2

    # Perform binary search in the found range
    return binary_search(arr, left, min(right, len(arr) - 1), target)

def binary_search_first_one(arr, left, right):
    #Perform binary search to find the first occurrence of 1 in the given range of the array.

    result = -1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == 1:
            result = mid
            right = mid - 1  # Continue searching in the left half
        else:
            left = mid + 1
    return result

def find_first_one_infinite_array(arr):
    #Find the index of the first 1 in an infinite binary sorted array.

    # Start with a box of size 1
    left, right = 0, 1

    # Exponentially increase the box size until we find a 1
    while right < len(arr) and arr[right] == 0:
        left = right
        right = right * 2

    # Perform binary search in the found range
    return binary_search_first_one(arr, left, min(right, len(arr) - 1))

def findPeakElement(arr: [int]) -> int:
    n = len(arr)
    if n == 1:
        return 0
    if arr[0] > arr[1]:
        return 0
    if arr[n - 1] > arr[n - 2]:
        return n - 1

    low, high = 1, n - 2
    while low <= high:
        mid = (low + high) // 2
        if arr[mid - 1] < arr[mid] and arr[mid] > arr[mid + 1]:
            return mid
        if arr[mid] > arr[mid - 1]:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binarySearchAscending(arr: [int], low: int, high: int, target: int) -> int:
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binarySearchDescending(arr: [int], low: int, high: int, target: int) -> int:
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] > target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def searchBitonicArray(arr: [int], target: int) -> int:
    peak = findPeakElement(arr)

    # Check if the peak is the target
    if arr[peak] == target:
        return peak

    # If target is greater than peak, it's not in the array
    if target > arr[peak]:
        return -1

    # Search in the left (ascending) part
    left_result = binarySearchAscending(arr, 0, peak - 1, target)
    if left_result != -1:
        return left_result

    # Search in the right (descending) part
    right_result = binarySearchDescending(arr, peak + 1, len(arr) - 1, target)
    return right_result

