        for char in s:
            ## check for the open parenthesis and add in to the stack 
            if char in "{[(":
                stack.append(char)
            else:
            ## check fot the close parenthesis 
                # If stack is empty then the open parenthesis doesn't exist so return False            
                if not stack:
