        # First pass: Pair up parentheses
        for i in range(n):
            if s[i] == '(':
                open_bracket_stack.append(i)
            elif s[i] == ')':
                j = open_bracket_stack.pop()
                # Two way mapping
                door[i] = j
                door[j] = i

        # Second pass: Build the result string
        result = []
        direction = 1  # 1 for left to right, -1 for right to left
        i = 0

        while i < n:
            if s[i] == '(' or s[i] == ')':
