    def longestValidParentheses(self, s: str) -> int:
        l_count = r_count = max_len = 0

        # Forward pass
        i = 0
        while i < len(s):
            if s[i] == '(':
                l_count += 1
            else:
                r_count += 1

            if l_count == r_count:
                max_len = max(max_len, l_count + r_count)
            elif r_count > l_count:
                l_count = r_count = 0

            i += 1

        # Reset counters
        l_count = r_count = 0

        # Backward pass
        i = len(s) - 1
        while i >= 0:
            if s[i] == '(':
                l_count += 1
            else:
                r_count += 1

            if l_count == r_count:
                max_len = max(max_len, l_count + r_count)
            elif l_count > r_count:
                l_count = r_count = 0

            i -= 1

        return max_len

