    return result

def find_kth_smallest(arr, k):
    # Use a max heap of size k
    heap = []
    for num in arr:
        if len(heap) < k:
            heapq.heappush(heap, -num)  # Push negative for max heap behavior
        elif -num > heap[0]:
            heapq.heappop(heap)
            heapq.heappush(heap, -num)
    return -heap[0]

