class StockPrice:

    def __init__(self):
        """
        particular stock - (timestamp and price), wrong order and some incorrect
        using red black tree to create a sorted dictionary to keep track of the timeprice and price_freq
        """
        import heapq
        self.stock_ticks = {}
        self.clock = 0
        self.min_heap = []
        self.max_heap = []

    def update(self, timestamp: int, price: int) -> None:
        self.stock_ticks[timestamp] = price
        heapq.heappush(self.max_heap, (-price, timestamp))
        heapq.heappush(self.min_heap, (price, timestamp))
        self.clock = max(self.clock, timestamp)

    def current(self) -> int:
        return self.stock_ticks[self.clock]

    def maximum(self) -> int:
        while self.max_heap:
            top_of_heap = self.max_heap[0]
            if self.stock_ticks[top_of_heap[1]] == -top_of_heap[0]:
                return -top_of_heap[0]
            heapq.heappop(self.max_heap)
        return 0

    def minimum(self) -> int:
        while self.min_heap:
            top_of_heap = self.min_heap[0]
            if self.stock_ticks[top_of_heap[1]] == top_of_heap[0]:
                return top_of_heap[0]
            heapq.heappop(self.min_heap)
        return 0

class StockPrice:
    def __init__(self):
        self.timestamp_price = SortedDict()  # timestamp -> price
        self.price_freq = SortedDict()       # price -> frequency

    def update(self, timestamp: int, price: int):
        # If price already exists at this timestamp
        if timestamp in self.timestamp_price:
            old_price = self.timestamp_price[timestamp]
            self.price_freq[old_price] -= 1
            if self.price_freq[old_price] == 0:
                del self.price_freq[old_price]

        # Update price
        self.timestamp_price[timestamp] = price
        self.price_freq[price] = self.price_freq.get(price, 0) + 1

    def current(self):
        return self.timestamp_price.peekitem(-1)[1]  # Last item

    def maximum(self):
        return self.price_freq.peekitem(-1)[0]  # Largest price

    def minimum(self):
        return self.price_freq.peekitem(0)[0]

class Solution:
    def totalCost(self, costs: List[int], k: int, candidates: int) -> int:
        """
        costs where cost of hiring the ith worker
        k and candidates
        k sessions and each session one worker 
        """
        import heapq
        front_heap = []
        back_heap = []
        front_index = 0
        back_index = len(costs) - 1

        for i in range(min(candidates, len(costs))):
            heapq.heappush(front_heap, (costs[front_index], front_index) )
            front_index += 1
        for i in range(min(candidates, len(costs)- front_index)):
            heapq.heappush(back_heap, (costs[back_index], back_index))
            back_index -= 1

        total_cost = 0
        hired = 0
        while hired < k and (front_heap or back_heap):
            if not front_heap:
                cost, idx = heapq.heappop(back_heap)
            elif not back_heap:
                cost, idx = heapq.heappop(front_heap)
            else:
                if front_heap[0] <= back_heap[0]:
                    cost, idx = heapq.heappop(front_heap)
                else:
                    cost, idx = heapq.heappop(back_heap)

            total_cost += cost
            hired += 1
            if front_index <= back_index:
                if idx < front_index:
                    if front_index <= back_index:
                        heapq.heappush(front_heap, (costs[front_index], front_index))
                        front_index += 1
                else:
                    if front_index <= back_index:
                        heapq.heappush(back_heap, (costs[back_index], back_index))
                        back_index -= 1
        return total_cost

class Solution:
    def kWeakestRowsbs(self, mat: List[List[int]], k: int) -> List[int]:
            """
            Time Complexity: O(mlogn+mlogm)
            Binary search on each row to find the number of soldiers will take O(logn) time for each row, resulting in O(mlogn) for all rows. Building and manipulating the heap will take O(mlogm) time.
            Space Complexity: O(m)
            We need additional space for the heap to store the strengths and indices, which will be of length m.

            """
            def binarySearch(arr):
                left, right = 0, len(arr) - 1
                while left <= right:
                    mid = (left + right) // 2
                    if arr[mid] == 1:
                        left = mid + 1
                    else:
                        right = mid - 1
                return left

            queue = [(binarySearch(row), idx) for idx, row in enumerate(mat)]
            heapq.heapify(queue)

            return [idx for _, idx in heapq.nsmallest(k, queue)]

