class Solution:
    def kthGrammar(self, n: int, k: int) -> int:
            if n == 1:
                return 0

            mid = (1 << (n - 2))  # Equivalent to 2^(n-2) ->  2**(n-2)

            if k <= mid:
                return self.kthGrammar(n - 1, k)
            else:
                # compliment of the input 
                return 1 - self.kthGrammar(n - 1, k - mid)

