            # Count empty cells and find the starting point
            for i in range(self.m):
                for j in range(self.n):
                    if grid[i][j] == 0:
                        self.empty_cells += 1
                    elif grid[i][j] == 1:
                        start_x, start_y = i, j

            # Add 1 to include the starting cell
            self.empty_cells += 1

            self.dfs(grid, 0, start_x, start_y)

            return self.result

