class Solution:
    def max_gain(self, node: TreeNode) -> int:
            if not node:
                return 0

            # Recursively find the maximum path sum for left and right subtrees
            left_gain = max(self.max_gain(node.left), 0)
            right_gain = max(self.max_gain(node.right), 0)

            # Price of the new path: node value + left gain + right gain
            price_new_path = node.val + left_gain + right_gain

            # Update max_sum if the new path price is higher
            self.max_sum = max(self.max_sum, price_new_path)

            # Return the maximum gain the node and one of its subtrees could add to the parent
            return node.val + max(left_gain, right_gain)

class Solution:
    def distanceK(self, root: TreeNode, target: TreeNode, k: int) -> List[int]:
        def add_parent_dfs(node, parent):
            if not node:
                return None
            node.parent = parent
            add_parent_dfs(node=node.left, parent=node)
            add_parent_dfs(node=node.right, parent=node)
            return

        add_parent_dfs(root, None)
        from collections import deque
        node_queue = deque()
        node_queue.append(target)
        visited_nodes = set([target])
        curr_iter = 0
        while node_queue:
            queue_len = len(node_queue)
            if curr_iter == k:
                return [node.val for node in node_queue]
            for _ in range(queue_len):
                curr_node = node_queue.popleft()
                for neighbor in [curr_node.parent, curr_node.left, curr_node.right]:
                    if not neighbor or neighbor in visited_nodes:
                        continue
                    node_queue.append(neighbor)
                    visited_nodes.add(neighbor)
            curr_iter += 1
        return []

