class Solution:
    def lowestCommonAncestorRecursive(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':
            if not root:
                return None

            curr = root.val

            # If both of them is in right then go to the right
            if curr < p.val and curr < q.val:
                return self.lowestCommonAncestor(root.right, p, q)

            # If both of them is in left then go to the right
            if curr > p.val and curr > q.val:
                return self.lowestCommonAncestor(root.left, p, q)

            ## If both of them are not in the same side then that is the iter section point 
            ## that is the LCA 
            return root

class TrieNode():
    def __init__(self, char):
        self.char = char
        self.children = {}
        self.end_of_word = False

class Trie():
    def __init__(self):
        self.root = TrieNode("")

    def insert(self, word):
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode(char)
            node = node.children[char]
        node.end_of_word = True       

    def search_prefix(self, prefix: str):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return False
            node = node.children[char]
        return True

    def search_word_exists(self, full_word):
        node = self.root
        for char in full_word:
            if char not in node.children:
                return False
            node = node.children[char]
        return node.end_of_word

