def has_cycle_kahns(V: int, adj: List[List[int]]) -> bool:
    # Calculate in-degree for each vertex
    in_degree = [0] * V
    for u in range(V):
        for v in adj[u]:
            in_degree[v] += 1

    # Initialize queue with vertices having 0 in-degree
    # queue = deque([u for u in range(V) if in_degree[u] == 0])
    queue = deque()
    for u in range(V):
        if in_degree[u] == 0:
            queue.append(u)

    visited_count = 0

    while queue:
        u = queue.popleft()
        visited_count += 1

        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # If not all vertices are visited, there's a cycle
    return visited_count != V

class Solution:
    def updateMatrix(self, mat: List[List[int]]) -> List[List[int]]:
        """
        start from the zeros and find their distance to one.
        TC: O(mn)
        """
        from collections import deque
        if not mat:
            return mat
        row_len = len(mat)
        col_len = len(mat[0])
        DIRECTIONS = [ (-1, 0), (1,0), (0,1), (0,-1) ]

        distance = [ [-1 for _ in range(col_len)] for _ in range(row_len) ]
        node_queue = deque([])

        def bfs():
            while node_queue:
                row, col, dist_from_0 = node_queue.pop()
                for x,y in DIRECTIONS:
                    nrow = row + x
                    ncol = col + y
                    if nrow < 0 or ncol < 0 or nrow >= row_len or ncol>=col_len:
                        continue
                    if distance[nrow][ncol] != -1:
                        continue
                    node_queue.appendleft( (nrow, ncol, dist_from_0 + 1))
                    distance[nrow][ncol] = dist_from_0 + 1

        for row in range(row_len):
            for col in range(col_len):
                if mat[row][col] == 0:
                    node_queue.appendleft((row, col, 0))
                    distance[row][col] = 0
        bfs()
        return distance

