class Solution:
    def DFS(self, maze: List[List[int]], x: int, y: int) -> bool:
            if x == self.end_x and y == self.end_y:
                return True

            if self.visited[x][y]:
                return False

            self.visited[x][y] = True
            for dx, dy in self.directions:
                x_, y_ = x + dx, y + dy

                # Continue moving in the same direction until hitting a wall
                while 0 <= x_ < len(maze) and 0 <= y_ < len(maze[0]) and maze[x_][y_] == 0:
                    x_ += dx
                    y_ += dy

                # Move back one step as we've hit a wall
                x_ -= dx
                y_ -= dy

                if not self.visited[x_][y_] and self.DFS(maze, x_, y_):
                    return True

            return False

