            # Initialize DSU
            self.parent = list(range(n))
            self.rank = [0] * n

            # Process all edges
            for u, v in edges:
                self.union(u, v)

            # Count the size of each connected component
            component_sizes = {}
            for i in range(n):
                parent = self.find(i)
                component_sizes[parent] = component_sizes.get(parent, 0) + 1

            result = 0
            remaining_nodes = n

