class Solution:
    def maxAreaOfIsland(self, grid: list[list[int]]) -> int:
        m, n = len(grid), len(grid[0])
        dsu = DSU(m * n)
        result = 0
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        def is_safe(x, y):
            return 0 <= x < m and 0 <= y < n and grid[x][y] == 1

        def link(i, j):
            index = i * n + j
            size = dsu.size[dsu.find(index)]

            for di, dj in directions:
                x, y = i + di, j + dj
                if is_safe(x, y):
                    size = max(size, dsu.union(index, x * n + y))

            return size

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    grid[i][j] = 0  # Mark as visited
                    result = max(result, link(i, j))

        return result

class UnionFind():
    def __init__(self, size=0):
        self.parent = list(range(size))
        self.rank = [0]*size
        self.size = [1]*size
        self.components = size

    def find(self, node):
        # Does path compression
        if self.parent[node] != node:
            self.parent[node] =  self.find(self.parent[node])
        return self.parent[node]

    def union_by_rank(self, source, target):
        psource = self.find(source)
        ptarget = self.find(target)
        if psource == ptarget:
            return False
        # Union by rank
        if self.rank[psource] > self.rank[ptarget]:
            self.parent[ptarget] = psource
        elif self.rank[psource] < self.rank[ptarget]:
            self.parent[psource] = ptarget
        else:
            self.parent[ptarget] = psource
            self.rank[psource] += 1
        self.components -= 1
        return True

