class Solution:
    def accountsMerge(self, accounts: list[list[str]]) -> list[list[str]]:
        n = len(accounts)
        dsu = DSU(n)

        # Create unions between indexes
        email_to_account = {}
        for i, (_, *emails) in enumerate(accounts):
            for email in emails:
                if email in email_to_account:
                    dsu.union(i, email_to_account[email])
                else:
                    email_to_account[email] = i

        # Group emails by their final owner
        merged_accounts = collections.defaultdict(list)
        for email, account_index in email_to_account.items():
            root = dsu.find(account_index)
            merged_accounts[root].append(email)

        # Format the output
