            self.size[x_parent] += self.size[y_parent]
        else:
            self.parent[x_parent] = y_parent
            self.size[y_parent] += self.size[x_parent]

        self.number_of_components -= 1

class Solution:
    def largestComponentSize(self, nums: list[int]) -> int:
        n = max(nums) + 1
        dsu = DSU(n)

        def factor_and_union(num):
            for i in range(2, int(num**0.5) + 1):
                if num % i == 0:
                    dsu.union(num, i)
                    dsu.union(num, num // i)

        for num in nums:
            factor_and_union(num)

        component_size = {}
        max_size = 0
        for num in nums:
            parent = dsu.find(num)
            component_size[parent] = component_size.get(parent, 0) + 1
            max_size = max(max_size, component_size[parent])

        return max_size

class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.number_of_components = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_parent, y_parent = self.find(x), self.find(y)
        if x_parent == y_parent:
            return

        if self.size[x_parent] > self.size[y_parent]:
            self.parent[y_parent] = x_parent
            self.size[x_parent] += self.size[y_parent]
        else:
            self.parent[x_parent] = y_parent
            self.size[y_parent] += self.size[x_parent]

        self.number_of_components -= 1

    def max_size(self):
        return self.number_of_components

class Solution:
    def canTraverseAllPairs(self, nums: list[int]) -> bool:
        n = len(nums)
        dsu = DSU(n)

        m = max(nums)
        first = [-1] * (m + 1)

        for i in range(n):
            num = nums[i]

            # Check for prime factors up to sqrt(num)
            for prime in range(2, int(num**0.5) + 1):
                if num % prime != 0:
                    continue

                if first[prime] != -1:
                    dsu.union(first[prime], i)
                else:
                    first[prime] = i

                while num % prime == 0:
                    num //= prime

            # Check if the remaining num is a prime factor > sqrt(nums[i])
            if num > 1:
                if first[num] != -1:
                    dsu.union(first[num], i)
                else:
                    first[num] = i

        return dsu.max_size() == 1

