class Solution:
    def buyChoco(self, prices: List[int], money: int) -> int:
        # Initialize the two smallest prices to a large value
        smallest = second_smallest = float('inf')

        # Iterate through the prices
        for price in prices:
            if price < smallest:
                # Update both smallest and second_smallest
                second_smallest = smallest
                smallest = price
            elif price < second_smallest:
                # Update only second_smallest
                second_smallest = price

        # Calculate the total cost of the two cheapest chocolates
        total_cost = smallest + second_smallest

        # Check if we can buy the chocolates and have non-negative leftover
        if total_cost <= money:
            return money - total_cost
        else:
            return money

def get_used_notes(amount, denominations):
    # Sort denominations in descending order
    denominations.sort(reverse=True)

    used_notes = {}

    for note in denominations:
        if amount >= note:
            count = amount // note
            used_notes[note] = count
            amount -= count * note

    # If there's still some amount left, it's not possible to make the exact change
    if amount > 0:
        return None

    return used_notes

