def backtrack(s, start, permutations):
    if start == len(s):
        permutations.append(''.join(s))
        return

    for i in range(start, len(s)):
        swap(s, start, i)  # swap
        backtrack(s, start + 1, permutations)  # recurse
        swap(s, start, i)

