                return nums[0]
            skip_last_max = self.rob_alternatively(nums[:len(nums)-1])
            skip_first_max = self.rob_alternatively(nums[1:])
            return max(skip_first_max, skip_last_max)

class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        """
        Time: Assuming the size of the dictionary is m, and string matching takes O(n), the overall time complexity is `O(n^2 * m).
        Space: O(n)
        """
        n = len(s)

        def dfs(starting_index) -> bool:
            if starting_index >= n:
                return True
            if starting_index in memo:
                return memo[starting_index]
            res = False
            for word in wordDict:
                if s[starting_index:].startswith(word):
                    res = res or dfs( starting_index + len(word))
                    if res:
                        break
            memo[starting_index] = res
            return res
        memo = {}
        can_break_word = dfs(0)
        return can_break_word

def knapsack_recursive(W, wt, val, n):
    # Base case: if we have no items or no capacity left
    if n == 0 or W == 0:
        return 0

    # If weight of the nth item is more than the capacity W,
    # then this item cannot be included
    if wt[n-1] > W:
        return knapsack_recursive(W, wt, val, n-1)

    else:
        # Return the maximum of two cases:
        # (1) nth item included
        # (2) nth item not included
        return max(
            val[n-1] + knapsack_recursive(W - wt[n-1], wt, val, n-1),
            knapsack_recursive(W, wt, val, n-1)
        )

def knapsack(W, wt, val, n):
    # Create a matrix of size K[n+1][W+1] as these variables are changing 
    # Initialize a table with 0's
    K = [[0 for _ in range(W + 1)] for _ in range(n + 1)]

    # Build table K[][] in bottom-up manner
    for i in range(n + 1):
        for j in range(W + 1):
            if i == 0 or j == 0:
                K[i][j] = 0
            elif wt[i-1] <= j:
                K[i][j] = max(val[i-1] + K[i-1][j-wt[i-1]],  K[i-1][j])
            else:
                K[i][j] = K[i-1][j]

    return K[n][W]

