def reconstruct_solution(length, prices):
    n = len(prices)
    wt = list(range(1, n + 1))
    val = prices
    K = [[0 for x in range(length + 1)] for x in range(n + 1)]

    for i in range(1, n + 1):
        for w in range(1, length + 1):
            if wt[i-1] <= w:
                K[i][w] = max(val[i-1] + K[i][w-wt[i-1]], K[i-1][w])
            else:
                K[i][w] = K[i-1][w]

    # Reconstruct the solution
    cuts = []
    i, w = n, length
    while i > 0 and w > 0:
        if K[i][w] != K[i-1][w]:
            cuts.append(wt[i-1])
            w -= wt[i-1]
        else:
            i -= 1

    return K[n][length], cuts

def coin_change_ways(amount, coins):
    n = len(coins)

    # Create lists for weights (coin denominations) and values (always 1 for counting)
    wt = coins
    val = [1] * n  # We're counting ways, so each coin contributes 1 to the count

    # Initialize a table with 0's
    K = [[0 for x in range(amount + 1)] for x in range(n + 1)]

    # Initialize the first row: one way to make amount 0
    for i in range(n + 1):
        K[i][0] = 1

    # Build table K[][] in bottom-up manner
    for i in range(1, n + 1):
        for w in range(1, amount + 1):
            if wt[i-1] <= w:
                # Instead of max, we use addition to count all possible ways
                K[i][w] = K[i][w-wt[i-1]] + K[i-1][w]
            else:
                K[i][w] = K[i-1][w]

    return K[n][amount]

def coin_change_min_coins(amount, coins):
    dp = [amount + 1] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        for i in range(coin, amount + 1):
            dp[i] = min(dp[i], dp[i - coin] + 1)

    return dp[amount] if dp[amount] <= amount else -1

