class Solution:
    def longestCommonSubsequence(self, X: str, Y: str, n: int, m: int) -> int:
        def lcs_recursive(n, m):
            # Base case: if either string is empty
            if n == 0 or m == 0:
                return 0

            # If last characters match
            if X[n-1] == Y[m-1]:
                return 1 + lcs_recursive(n-1, m-1)

            # If last characters don't match
            else:
                return max(lcs_recursive(n-1, m),
                           lcs_recursive(n, m-1))

        return lcs_recursive(n, m)

class Solution:
    def longestCommonSubsequence(self, X: str, Y: str) -> int:
        def lcs_recursive(i: int, j: int) -> int:
            # Base case: if we've reached the end of either string
            if i == 0 or j == 0:
                return 0

            # Check if we've already computed this subproblem
            if memo[i][j] != -1:
                return memo[i][j]

            # If the characters match
            if X[i-1] == Y[j-1]:
                memo[i][j] = 1 + lcs_recursive(i-1, j-1)
            else:
                # If the characters don't match, we have two choices:
                # 1. Exclude the character from X
                # 2. Exclude the character from Y
                # We take the maximum of these two choices
                memo[i][j] = max(lcs_recursive(i-1, j), lcs_recursive(i, j-1))

            return memo[i][j]

        # Initialize memoization table with -1
        m, n = len(X), len(Y)
        memo = [[-1 for _ in range(n+1)] for _ in range(m+1)]

        # Call the recursive function
        return lcs_recursive(m, n)

def longestCommonSubsequence(X: str, Y: str) -> int:
    """
    Compute the length of the Longest Common Subsequence (LCS) of strings X and Y using tabulation.

    This function uses a bottom-up dynamic programming approach to solve the LCS problem.

    Args:
    X (str): The first input string
    Y (str): The second input string

    Returns:
    int: The length of the longest common subsequence
    """
    m = len(X)
    n = len(Y)

    # Create a DP table of size (m+1) x (n+1) initialized with -1
    t = [[-1 for j in range(n + 1)] for i in range(m + 1)]

    # Initialize the base cases:
    # - The length of LCS with an empty string is 0, so t[i][0] = 0 for all i
    # - The length of LCS with an empty string is 0, so t[0][j] = 0 for all j
    for i in range(m + 1):
        t[i][0] = 0
    for j in range(n + 1):
        t[0][j] = 0

    # Fill in the DP table by considering characters from both strings
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i - 1] == Y[j - 1]:
                # If the characters match, increment the LCS length
                t[i][j] = 1 + t[i - 1][j - 1]
            else:
                # If the characters do not match, take the maximum of
                # LCS length without one character from X or Y
                t[i][j] = max(t[i - 1][j], t[i][j - 1])

    # The value in t[m][n] represents the length of the Longest Common Subsequence
    return t[m][n]

class Solution:
    def printLongestCommonSubstring(self, X: str, Y: str) -> str:
            """
            Function to print the longest common substring using the top-down approach.
            """
            m, n = len(X), len(Y)
            dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

            max_length = 0
            end_index = 0

            # Fill the DP table and keep track of the maximum length and end index
            for i in range(1, m + 1):
                for j in range(1, n + 1):
                    if X[i-1] == Y[j-1]:
                        dp[i][j] = dp[i-1][j-1] + 1
                        if dp[i][j] > max_length:
                            max_length = dp[i][j]
                            end_index = i - 1
                    else:
                        dp[i][j] = 0

            # Extract the substring using the end index and length
            start_index = end_index - max_length + 1
            return X[start_index:end_index + 1]

def printLongestRepeatingSubsequence(s: str) -> str:
    """
    Compute and return the Longest Repeating Subsequence.

    Args:
    s (str): The input string

    Returns:
    str: The longest repeating subsequence
    """
    n = len(s)
    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s[i - 1] == s[j - 1] and i != j:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the longest repeating subsequence
    lrs = []
    i, j = n, n
    while i > 0 and j > 0:
        if s[i - 1] == s[j - 1] and i != j:
            lrs.append(s[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(reversed(lrs))

class TrieNode():
    def __init__(self, char):
        self.char = char
        self.end_word = False
        self.children = [0]*26

class Trie():
    def __init__(self):
        self.root = TrieNode("")

    def add_word(self, word):
        node = self.root
        for char in word:
            char_index = ord(char) - ord('a')
            if node.children[char_index] == 0:
                node.children[char_index] = TrieNode(char)
            node = node.children[char_index]
        node.end_word = True


    def search_n_suggest(self, searchWord) -> List:
        suggestions = []
        node = self.root
        prefix_str = ""
        prefix = searchWord
        for char in prefix:
            prefix_str += char
            char_index = ord(char) - ord('a')
            if node.children[char_index] == 0:
                suggestions.extend(
                     [[]]* (len(searchWord) - len(prefix_str) + 1) )
                break
            node = node.children[char_index]
            suggestions.append(self.collect_suggestions(node, prefix_str=prefix_str, suggestions=[]))
        return suggestions

    def collect_suggestions(self, prefix_node, prefix_str:str, suggestions: List) -> List[str]:
        if prefix_node.end_word:
            suggestions.append(prefix_str)
        if len(suggestions) == 3:
            return suggestions
        results = []
        for node in prefix_node.children:
            if node == 0:
                continue
            self.collect_suggestions(node, prefix_str+node.char, suggestions)
            if len(suggestions) == 3:
                return suggestions
        return suggestions

class Solution:
    def suggestedProducts(self, products: List[str], searchWord: str) -> List[List[str]]:
        prefix_tree = Trie()
        root = prefix_tree.root
        for product in products:
            prefix_tree.add_word(product)
        suggestions = prefix_tree.search_n_suggest(searchWord)
        return suggestions
